    [2547]={name="Boar Handler Gloves",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Dwarven Outfitters'. Pick it over the other reward choices. Starts with Sten Stoutarm in Dun Morogh. Objective: Sten Stoutarm would like 8 pieces of Tough Wolf Meat.",zone="Dun Morogh",questName="Dwarven Outfitters",lore="You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."},
